def _dados_iniciais() -> None:
    agora = datetime.now(UTC)
    t = sa.table("tipo_amostra", sa.column("id", sa.Uuid), sa.column("codigo"), sa.column("nome"), sa.column("geometria"),
                 sa.column("ativo"), sa.column("versao"), sa.column("criado_em", sa.DateTime(timezone=True)))
    op.bulk_insert(t, [{"id": uuid.uuid4(), "codigo": c, "nome": n, "geometria": g, "ativo": True, "versao": 1,
                        "criado_em": agora} for c, n, g in TIPOS])
    t_perm = sa.table("permissao", sa.column("id", sa.Uuid), sa.column("codigo"), sa.column("descricao"))
    op.bulk_insert(t_perm, [{"id": uuid.uuid4(), "codigo": c, "descricao": d} for c, (d, _) in PERMISSOES.items()])
    for codigo, (_d, papeis) in PERMISSOES.items():
        lista = ",".join(f"'{p}'" for p in papeis)
        op.execute(sa.text("INSERT INTO papel_permissao (papel_id, permissao_id) SELECT p.id, m.id FROM papel p, "
                           f"permissao m WHERE p.codigo IN ({lista}) AND m.codigo = '{codigo}'"))
